<div class="s-panel" id="s-panel" role="tabpanel" tabindex="-1" aria-labelledby="s-tab-clinic"><header class="s-head"><div style=""><h2 class="s-head__title">Clinic</h2><p class="card__sub">Your clinic’s details, used across Tend and in patient messages.</p></div><span class="s-saved" data-saved="" aria-live="polite" style=""></span></header>
    <div class="s-cards s-cards--clinic"><section class="card s-card " style=""><header class="card__head"><div><h3 class="card__title">Clinic details</h3><p class="card__sub">Changes save as soon as you leave a field.</p></div></header><form class="s-fields" data-form="clinic" novalidate="">
      <label class="field" for="s-c-name" style=""><span class="field__label">Clinic name</span><input id="s-c-name" name="name" type="text" value="Northside Family Clinic" autocomplete="organization" required=""></label>
      <label class="field" for="s-c-phone" style=""><span class="field__label">Front desk phone</span><input id="s-c-phone" name="phone" type="tel" value="+1 (415) 555-0142" autocomplete="tel" required=""></label>
      <label class="field field--wide" for="s-c-address" style=""><span class="field__label">Address</span><input id="s-c-address" name="address" type="text" value="24 Harbor St, Suite 3" autocomplete="street-address" required=""><span class="field__hint">Shown in confirmations and directions.</span></label>
      <label class="field" for="s-c-tz" style=""><span class="field__label">Time zone</span><select id="s-c-tz" name="timezone"><option value="America/Los_Angeles" selected="">Pacific Time — Los Angeles</option><option value="America/Denver">Mountain Time — Denver</option><option value="America/Phoenix">Mountain Time — Phoenix</option><option value="America/Chicago">Central Time — Chicago</option><option value="America/New_York">Eastern Time — New York</option><option value="America/Anchorage">Alaska Time — Anchorage</option><option value="Pacific/Honolulu">Hawaii Time — Honolulu</option><option value="Europe/London">UK Time — London</option><option value="Asia/Dubai">Gulf Time — Dubai</option><option value="Asia/Dhaka">Bangladesh Time — Dhaka</option></select><span class="field__hint">Reminders go out in the clinic’s time.</span></label>
      <label class="field" for="s-c-slot" style=""><span class="field__label">Default slot length</span><select id="s-c-slot" name="slotMins"><option value="10">10 minutes</option><option value="15" selected="">15 minutes</option><option value="20">20 minutes</option><option value="30">30 minutes</option></select><span class="field__hint">New bookings snap to this grid.</span></label>
    </form></section><section class="card s-card " style=""><header class="card__head"><div><h3 class="card__title">Patients see</h3><p class="card__sub">Your WhatsApp business profile.</p></div></header><div class="wa-wall s-profile">
      <span class="s-profile__mark" aria-hidden="true"><svg class="ico " viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M12 20.5s-7.5-4.4-7.5-10.2A4.3 4.3 0 0 1 12 7.6a4.3 4.3 0 0 1 7.5 2.7c0 5.8-7.5 10.2-7.5 10.2Z"></path><path d="M8.5 12.5h2l1-2 1.6 4 1-2h1.4"></path></svg></span>
      <b class="s-profile__name" data-prof="name">Northside Family Clinic</b>
      <small class="s-profile__kind"><svg class="ico " viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m5 12.5 4.5 4.5L19 7.5"></path></svg>Business account</small>
      <ul class="s-profile__rows">
        <li><svg class="ico " viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M12 21s-6.5-5.6-6.5-11a6.5 6.5 0 0 1 13 0c0 5.4-6.5 11-6.5 11Z"></path><circle cx="12" cy="10" r="2.3"></circle></svg><span data-prof="address">24 Harbor St, Suite 3</span></li>
        <li><svg class="ico " viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M6.5 3.5h3l1.5 4-2 1.5a11 11 0 0 0 6 6l1.5-2 4 1.5v3a2 2 0 0 1-2 2A16 16 0 0 1 4.5 5.5a2 2 0 0 1 2-2z"></path></svg><span data-prof="phone">+1 (415) 555-0142</span></li>
        <li><svg class="ico " viewBox="0 0 24 24" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="8.5"></circle><path d="M12 7.5V12l3 2"></path></svg><span>Open today 8:00 AM – 5:00 PM</span></li>
      </ul>
    </div></section></div></div>
